<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Vec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Str</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pathSegments;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // e.g. [&quot;std&quot;, &quot;prelude&quot;]</span></span>
